from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
def concept(k,title,p1,p2,ids):add('e40-'+k,title,'<p>'+p1+'</p><p>'+p2+'</p>',ids)
concept('definition','Kwashiorkor : tableau clinique et périmètre','Le kwashiorkor est une forme grave de malnutrition œdémateuse, souvent accompagnée de signes de peau, cheveux ou foie. L’OMS2026 précise que son origine exacte et ses différences avec le marasme restent incomplètement comprises. Une explication par les protéines seules est trop réductrice.','L’OFS2024 décrit E40 comme malnutrition grave avec œdème nutritionnel et dépigmentation peau/cheveux, avec exclusion du marasme associé vers E42. Le libellé d’un code et les critères de prise en charge ne sont pas la même question.',('CH-CIM','INT-WHO-EDEMA'))
concept('nutritional-edema','Œdème nutritionnel : qualifier avant de classer','Dans le guide pédiatrique2026, l’œdème nutritionnel est bilatéral, commence aux pieds et peut s’étendre. Son identification peut suffire à classer une MAS chez l’enfant sans imposer un poids/taille bas en plus.','Cette règle n’autorise pas à qualifier de nutritionnel tout œdème bilatéral. Début ailleurs, asymétrie, protéinurie ou signes d’organe conduisent à une recherche différentielle ; les causes peuvent coexister.',('INT-WHO-EDEMA','INT-WHO-IDENT'))
concept('grade','Gradation OMS/UNICEF2026 des œdèmes','Grade+ : deux pieds seuls. Grade++ : pieds et jambes. Grade+++ : pieds et jambes avec toute autre partie, dont le visage. Cette version diffère de tableaux plus anciens qui plaçaient mains/bras dans une catégorie intermédiaire.','Pour les six à cinquante-neuf mois avec MAS,+++ est un motif d’hospitalisation immédiate. Noter la distribution en mots et la version évite qu’un même nombre de signes+ cache deux définitions différentes.',('INT-WHO-EDEMA','INT-WHO-TRIAGE'))
concept('marasmus','Marasme, kwashiorkor et association','Le marasme nutritionnel correspond à une forme avec déplétion tissulaire importante ; dans la nomenclature consultée E41 est distinct d’E40. L’eau peut masquer une partie de la maigreur dans un tableau œdémateux.','L’association kwashiorkor et marasme relève d’E42. E43, qui inclut œdème de famine et malnutrition grave sans précision, ne doit pas être substitué mécaniquement sans vérifier la documentation clinique.',('CH-CIM','CH-CIM-BOUND'))
concept('albumin','Albumine : concentration et mécanismes','L’albumine contribue à la pression oncotique du plasma. Sa concentration varie avec plusieurs processus, dont inflammation, synthèse et pertes ; elle ne constitue pas un compteur de protéines alimentaires ingérées.','GLIM déconseille l’hypoalbuminémie comme indicateur isolé de dénutrition. Les cohortes pédiatriques2022 montrent aussi que l’œdème ne se résume pas à sa concentration. Pas de seuil d’albumine inventé pour diagnostiquer universellement E40.',('INT-GLIM','EU-EDEMA-MECH','EU-EDEMA-LIMIT'))
concept('starling','Échanges liquidiens : capillaire, interstitium et lymphatique','Le mouvement d’eau dépend notamment des pressions, de la barrière vasculaire, des protéines, de la matrice interstitielle et du drainage lymphatique. La description classique d’une réabsorption veineuse systématique de tout liquide filtré est insuffisante.','L’étude2022 propose des mécanismes liés à la matrice et au lymphatique dans la malnutrition sévère de l’enfant. Ce sont des résultats de groupes sélectionnés ; ils n’établissent pas une prescription d’albumine ni un test de routine chez tout adulte.',('EU-EDEMA-MECH','EU-EDEMA-LIMIT','NORMAL-LYMPH'))
concept('refeeding','Syndrome de renutrition : une complication de trajectoire','Après restriction prolongée, la reprise des apports, surtout glucidiques, augmente les besoins métaboliques et modifie les électrolytes et l’eau. Les manifestations peuvent être cardiaques, respiratoires ou neurologiques.','La revue suisse concerne les adultes médicaux, hors troubles alimentaires, et reconnaît des preuves souvent limitées. Le protocole pédiatrique OMS a sa propre prévention et surveillance ; œdème initial et complication de renutrition ne sont pas synonymes.',('CH-RFS-MECH','CH-RFS-LIMIT','INT-WHO-RFS'))
concept('microbiome','Écosystème intestinal : mécanisme et limite thérapeutique','La barrière intestinale, les microorganismes et l’immunité interagissent avec nutrition et infection. Le guide OMS évoque la flore intestinale parmi les mécanismes possibles du bénéfice antibiotique dans son circuit MAS.','Une hypothèse ne crée pas une indication de probiotique ou d’autre manipulation du microbiote. Les données immunitaires sont hétérogènes et souvent confondues par les infections ; les causes alimentaires et organiques doivent être examinées.',('EU-IMMUNE','INT-WHO-ABX'))
concept('anthropometry','Anthropométrie : mesurer tissu, croissance et eau','Poids, longueur/taille, périmètre brachial et muscle répondent à des questions différentes. Utiliser technique, matériel, âge et référence appropriés, avec mesures antérieures fiables lorsqu’elles existent.','L’œdème augmente le poids et perturbe certaines mesures corporelles. Pendant sa résolution, le poids peut baisser alors que l’état s’améliore. Associer mesure, examen et trajectoire plutôt que choisir une étiquette sur un seul chiffre.',('INT-WHO-IDENT','INT-WHO-FEED','INT-GLIM'))
concept('muac','Périmètre brachial : le seuil dépend de l’âge','Entre six et cinquante-neuf mois, PB<115mm est un des critères OMS de MAS, indépendamment des deux autres critères possibles. Une mesure correcte et son âge sont nécessaires.','Entre six semaines et moins de six mois, PB<110mm identifie un risque de mauvaise croissance/développement ; il ne définit pas seul MAS. Le nourrisson peut avoir MAS avec œdème nutritionnel ou P/L<-3z. Aucun de ces seuils ne devient un seuil adulte.',('INT-WHO-IDENT',))
concept('zscore','Z-score : écart à une référence, pas pourcentage','Un z-score situe une mesure par rapport à une distribution de référence, avec âge, sexe et méthode appropriés. Il ne signifie ni pourcentage du poids attendu ni nombre de kilogrammes manquants.','Dans le cadre OMS6–59mois, P/T ou P/L<-3z est un critère de MAS ; l’œdème nutritionnel peut aussi la définir même sans ce seuil. Ne pas appliquer les descriptions statistiques historiques du codage comme critères GLIM adultes.',('INT-WHO-IDENT','CH-CIM-BOUND'))
concept('glim','GLIM2025 : diagnostic adulte mondial conjoint','GLIM est un consensus mondial associant ASPEN, ESPEN, FELANPE et PENSA, publié en2025 dans JPEN. Après dépistage, au moins un critère phénotypique et un étiologique sont nécessaires.','Phénotypes : perte de poids, IMC bas, muscle réduit. Étiologies : apports/assimilation réduits ou inflammation/charge morbide. Sévérité fondée sur le phénotype ; albumine seule insuffisante. Ce cadre adulte n’est pas une définition OMS du nourrisson ni un code E40 automatique.',('INT-GLIM','EU-ESPEN-SCREEN'))
concept('history','Anamnèse nutritionnelle : le repas réel','Demander ce qui est proposé, préparé, donné et réellement avalé, puis ce qui est vomi ou perdu. Durée de restriction, dysphagie, douleur, diarrhée, maladies et médicaments modifient l’explication.','Chez l’enfant, évaluer développement et aidant ; avant six mois, regarder la dyade et l’allaitement. Chez l’adulte, inclure autonomie, courses, cuisine et contexte social. Une absence de prise n’est pas expliquée par une simple ordonnance calorique.',('INT-WHO-TRIAGE','INT-WHO-INFANT','EU-ESPEN-SCREEN'))
concept('pitting','Godet : geste et non-spécificité','Le guide2026 propose une pression modérée pendant trois secondes au dos du pied ou à la face antérieure du tibia, puis l’observation d’une dépression persistante. Comparer côtés et extension.','Le godet décrit un signe d’eau interstitielle. La photographie de ce cours vient d’un cas hépatique, pas de kwashiorkor. L’examen et le bilan recherchent la cause ; une image n’établit ni bilatéralité ni statut circulant.',('INT-WHO-EDEMA','IMG-EDEMA'))
concept('skin','Peau, cheveux et muqueuses','Le guide décrit dermatose avec dépigmentation/desquamation et cheveux cassants ou hypopigmentés dans certains tableaux œdémateux. Examiner aussi bouche, yeux et signes d’infection selon contexte.','Une photographie historique peut montrer une anomalie sans en prouver le mécanisme. Une lésion commissurale n’identifie pas à elle seule une vitamine manquante ; une peau rouge n’est pas un signe spécifique E40.',('INT-WHO-EDEMA','IMG-KWA','IMG-EDEMA'))
concept('liver-exam','Hépatomégalie : constater puis expliquer','Une hépatomégalie peut accompagner le tableau pédiatrique de kwashiorkor. Son examen se relie aux autres signes et à l’histoire ; un foie palpable ne prouve pas seul une stéatose ou une défaillance.','La planche hépatique est normale. Elle situe hile, veine porte, vésicule et lobes, mais ne mesure ni taille du foie du patient ni albumine. Bilan et imagerie sont demandés selon une question clinique.',('INT-WHO-EDEMA','IMG-LIVER','INT-GLIM'))
concept('shock','Hypoperfusion : l’œdème ne garantit pas la volémie','Tachycardie, mauvaise perfusion, altération de conscience ou dégradation doivent faire rechercher une urgence. La présence de liquide dans les tissus ne prouve pas que la circulation est adéquate.','Chez l’enfant MAS, les protocoles d’urgence diffèrent de ceux sans MAS et de ceux de l’adulte. Le service choisit liquide, rythme, surveillance et traitement causal ; aucun remplissage uniforme n’est déduit du seul poids œdémateux.',('INT-WHO-TRIAGE','INT-WHO-IDENT','INT-WHO-RFS'))
concept('glucose','Glycémie : sécurité immédiate et suivi','Une hypoglycémie peut contribuer à somnolence, crise ou altération de conscience, mais ces signes ont plusieurs causes. Mesurer rapidement et traiter selon le protocole de la population sans retarder la stabilisation.','Pendant renutrition, hypo- ou hyperglycémie peut aussi apparaître. Associer valeur, prise effective, infection, organes et autres électrolytes ; une glycémie ponctuelle n’exclut pas une complication ultérieure.',('INT-WHO-TRIAGE','INT-WHO-RFS','CH-RFS-MECH'))
concept('tests','Bilan biologique : diagnostic, cause et sécurité','Glycémie, P/K/Mg et fonction rénale peuvent répondre à une question de sécurité ; hémogramme, inflammation, foie ou urines à une question étiologique. Adapter au patient et à l’urgence.','Les intervalles de référence dépendent du laboratoire, de l’âge et des unités. Un dosage normal initial peut coexister avec réserves appauvries ; le suivi pendant reprise est parfois plus informatif qu’une seule valeur.',('CH-RFS-MGMT','INT-WHO-RFS','INT-GLIM'))
concept('urine','Protéinurie : ne pas manquer une perte rénale','Une protéinurie peut orienter vers une cause rénale de l’œdème et de la baisse d’albumine. La bandelette est un repérage, à interpréter et à compléter selon contexte.','Une cause rénale n’exclut pas une dénutrition concomitante. Elle change toutefois l’enquête, la prescription hydrique et les précautions de médicaments ; la FI orale SpirigHC prévoit un circuit parentéral pour enfant insuffisant rénal.',('INT-WHO-EDEMA','FI-AMOX','INT-GLIM'))
concept('crp','CRP : marqueur de contexte','Le consensus GLIM admet qu’une maladie habituellement inflammatoire peut satisfaire son critère étiologique sans exiger toujours un marqueur. En cas de doute, la CRP peut aider à documenter l’inflammation.','Une CRP ne donne pas seule la cause de l’œdème ou de l’anorexie. Inflammation et pertes protéiques ou apports réduits peuvent se combiner ; ne pas attribuer toute albumine basse à la seule nourriture.',('INT-GLIM','EU-IMMUNE'))
concept('differential','Différentiels : chercher ce qui change le traitement','Œdèmes rénaux, hépatiques, cardiaques, locaux ou infectieux peuvent partager le godet. Début, symétrie, douleur, signes d’organe et urines orientent le bilan.','Après reprise alimentaire, penser aussi au syndrome de renutrition avec ses diagnostics concurrents. Les causes peuvent s’additionner ; reconnaître une dénutrition ne dispense pas de chercher une infection ou une maladie organique.',('INT-WHO-EDEMA','INT-WHO-RFS','CH-RFS-MECH'))
concept('admission','Hospitalisation : critères pédiatriques attribués','Chez l’enfant6–59mois avec MAS, les indications immédiates OMS2026 comprennent signe de danger IMCI, problème médical aigu, œdème+++ ou échec du test d’appétit.','Ce n’est pas un score d’hospitalisation adulte. Avant six mois, la branche clinique est distincte ; les mesures détaillées et l’histoire se font après triage/stabilisation si l’état l’exige.',('INT-WHO-TRIAGE','INT-WHO-INFANT'))
concept('stabilization','Stabilisation6–59mois : ne pas confondre avec rattrapage','Le guide2026 donne F75 à80–100kcal/kg/j pour la stabilisation, souvent le bas de fourchette en cas d’instabilité ou risque/tolérance défavorable. F75 contient75kcal/100mL ; huit repas quotidiens sont idéalement répartis toutes les trois heures.','L’équipe utilise le poids d’admission ou après réhydratation et adapte si œdème++/+++ rend le poids trompeur. Une perte de poids peut accompagner la résolution de l’eau ; augmenter brutalement parce que la balance baisse serait une erreur.',('INT-WHO-FEED',))
concept('transition','Transition : une phase avec critères','Après stabilisation des problèmes médicaux, retour d’appétit et diminution de l’œdème, le passage vers RUTF ou F100 se fait progressivement. La plage100–130kcal/kg/j du guide2026 appartient à cette phase6–59mois.','Réapparition d’un danger, surcharge, aggravation d’œdème ou diarrhée avec déshydratation exige réévaluation et possible retour à stabilisation. Un repas plus énergétique ne signifie pas que tout patient doit accélérer.',('INT-WHO-TRANS','INT-WHO-RFS'))
concept('rutf','RUTF et laits thérapeutiques','RUTF signifie aliment thérapeutique prêt à l’emploi, formulation standardisée utilisée dans des phases et circuits précis. F75 et F100 sont des laits thérapeutiques avec des densités énergétiques différentes.','Ce sont des aliments, pas une classe de médicaments dotée ici d’une FI suisse fictive. Avant six mois, soutien allaitement et supplémentation surveillée suivent des indications propres ; aucune recette domestique de dilution n’est donnée.',('INT-WHO-FEED','INT-WHO-TRANS','INT-WHO-INFANT'))
concept('adult','Adulte : dépistage, diagnostic, objectifs et risque','ESPEN recommande le dépistage validé chez l’adulte médical polymorbide hospitalisé, puis un plan adapté. GLIM relie phénotype et étiologie ; les objectifs énergétiques/protéiques ne constituent pas des critères diagnostiques E40.','Le risque de renutrition modifie la progression initiale. La revue suisse2019 propose5–15kcal/kg/j selon risque, tandis que l’ESPEN décrit des objectifs à atteindre prudemment. Il ne faut ni démarrer tous à30kcal/kg/j ni copier80–100kcal/kg/j de l’enfant.',('EU-ESPEN-SCREEN','EU-ESPEN-TARGET','INT-GLIM','CH-RFS-MGMT'))
concept('thiamine','Thiamine : mécanisme, voie et dose','La thiamine est un cofacteur nécessaire au métabolisme glucidique ; ses besoins augmentent lors de la reprise. La revue suisse adulte propose200–300mg avant renutrition, avec son champ et ses limites.','La FI Benerva distingue200–300mg/j oral pour hypovitaminose grave et jusqu’à200mg/j parentéral dans les cas sévères ; IV très lente à l’hôpital. Ni la voie ni la dose du nourrisson ne se déduisent de cette phrase adulte.',('CH-RFS-MGMT','FI-B1'))
concept('amoxicillin','Amoxicilline : deux référentiels sans fusion','OMS2026 MAS pédiatrique :50mg/kg par prise deuxfois/j pour son schéma oral, avec circuit et durée propres. FI SpirigHC200mg/4mL : enfant≤40kg50–100mg/kg/j en3–4prises, maximum2000mg/j.','Le total journalier peut sembler comparable sans que la répartition ni l’indication soient identiques. Vérifier concentration prête à l’emploi, prescription, fonction rénale et résistances ; ampicilline n’est pas un autre nom de l’amoxicilline.',('INT-WHO-ABX','FI-AMOX'))
concept('calculation','Calcul : mg/kg/prise, mg/kg/j et mL','Exemple fictif du schéma OMS, déjà choisi par équipe :50mg/kg/prise×8kg=400mg/prise. Si le produit identifié est à50mg/mL,400÷50=8mL/prise ; deux prises donnent800mg/j et16mL/j. Ce calcul ne prescrit pas la dose.','Avec une suspension25mg/mL,400mg correspondraient à16mL par prise. La concentration change le volume, pas la quantité de principe actif prescrite. Le schéma FI3–4prises reste distinct ; vérifier unités, produit et dispositif oral gradué.',('INT-WHO-ABX','FI-AMOX'))
concept('follow','Suivi : transfert et guérison nutritionnelle','La stabilisation permet un transfert lorsque le relais est sûr, mais ne signifie pas fin de traitement. Le poids doit être lu avec l’œdème et les prises ; absence d’amélioration appelle une réévaluation de maladie, prescription et mise en œuvre.','Pour MAS6–59mois, la fin demande habituellement P/T≥-2z, PB≥125mm et absence d’œdème sur deux visites/mesures, avec prise en charge des problèmes médicaux et sociaux. Discordances prolongées nécessitent décision clinique documentée ; pourcentage de poids gagné seul insuffisant.',('INT-WHO-FOLLOW',))
concept('prevention','Prévenir la rechute : rendre les repas possibles','Accès alimentaire, conseils adaptés, soins, soutien aidant, développement et prévention infectieuse font partie du parcours pédiatrique. Une prescription nutritionnelle sans possibilité de l’appliquer reste incomplète.','Chez l’adulte, identifier dépendance, problèmes de repas et maladies sous-jacentes, puis organiser suivi et soutien. Les besoins et la faisabilité se réévaluent ; aucun délai de guérison ni bénéfice intégral n’est garanti.',('INT-WHO-FOLLOW','INT-WHO-INFANT','EU-ESPEN-SCREEN'))
concept('populations','Populations : les différences changent la conduite','Avant six mois, croissance, dyade et allaitement occupent une place centrale ; six à cinquante-neuf mois, les critères OMS et circuits MAS sont différents ; chez l’adulte, GLIM/ESPEN apportent un autre cadre.','Grossesse/allaitement, insuffisances d’organe et âge modifient les précautions de produits. Le code E40 n’annule pas la FI, la fonction rénale ou le besoin d’une équipe spécialisée ; pas d’extension automatique des doses pédiatriques à tous adultes.',('INT-WHO-IDENT','INT-WHO-INFANT','INT-GLIM','FI-B1','FI-AMOX'))
concept('coding','Coder après avoir caractérisé','La version OFS consultée est CIM-10-GM2024. E40 n’a pas de sous-code décimal ; association au marasme vers E42, marasme seul E41 et malnutrition grave sans précision E43 selon documentation.','Un critère de programme OMS et un diagnostic GLIM adulte ne dictent pas seuls le code. Conserver maladie causale, phénotype nutritionnel et complications ; une nomenclature historique n’est pas un protocole de prescription.',('CH-CIM','CH-CIM-BOUND','INT-WHO-IDENT','INT-GLIM'))
summary=[('E40 a un périmètre précis ; la cause exacte du kwashiorkor ne se réduit pas aux protéines seules.','CH-CIM'),('Aucune incidence suisse directe E40 retenue ; ne pas remplacer son dénominateur par toute dénutrition.','EU-IMMUNE'),('Eau, tissu, albumine et drainage lymphatique sont des questions liées mais distinctes.','EU-EDEMA-MECH'),('Trier, décrire l’œdème, évaluer la nutrition, chercher les causes puis choisir le circuit.','INT-WHO-TRIAGE'),('Décrire ce qui est réellement avalé et perdu, avec trajectoire, maladie et environnement.','EU-ESPEN-SCREEN'),('Le godet exige un geste ; sa cause et sa gravité demandent tout l’examen.','INT-WHO-EDEMA'),('Malnutrition, inflammation, instabilité et renutrition peuvent se combiner sans être synonymes.','CH-RFS-MECH'),('Les critères enfant et adulte sont distincts ; avant six mois, le risque de croissance n’est pas toujours MAS.','INT-WHO-IDENT'),('Choisir des examens qui recherchent cause ou complication ; albumine seule insuffisante.','INT-GLIM'),('Garder causes rénales, hépatiques, cardiaques, digestives et locales dans le raisonnement.','INT-WHO-EDEMA'),('Prescrire selon âge, phase, voie et produit ; ne pas fusionner OMS, FI et objectifs adultes.','INT-WHO-FEED'),('Une variation de poids peut être hydrique ; transfert et fin du traitement sont différents.','INT-WHO-FOLLOW'),('Le contexte et les unités donnent leur sens aux chiffres.','FI-AMOX'),('Ni photo, ni albumine, ni code ne remplace le raisonnement et la prescription appropriée.','CH-CIM-BOUND')]
path=CH/'E40_a.html';txt=path.read_text()
for i,(essential,sid) in enumerate(summary,1):
 m=re.search(r'(<section\b[^>]*id="e40-'+str(i)+r'"[^>]*>)(.*?)(</section>)',txt,re.S);assert m
 soup=BeautifulSoup(m[2],'html.parser');title=soup.find(['h2','h3']).get_text(' ',strip=True);paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2]
 refs=list(dict.fromkeys(a.get_text().split(' — ')[0] for a in soup.select('a[data-reference-source]')))
 add('e40-exp-'+str(i),'Comprendre — '+title,'<p><b>Lecture expliquée.</b> '+essential+'</p>'+''.join('<p>'+p+'</p>' for p in paras),refs)
 add('pareto-e40-'+str(i),'Essentiel — '+title,'<p>'+essential+'</p>'+key('Préciser population, mécanisme, unités et décision.'),(sid,))
 entry='<p>'+w('exp-'+str(i),'Comprendre ce point')+' <button class="pareto-btn ui" data-k="pareto-e40-'+str(i)+'">▲ Loi de Pareto — l’essentiel</button></p>'
 txt=txt[:m.end(2)]+entry+txt[m.end(2):]
cases=[('Le poids masque l’œdème','Un enfant de vingt mois présente un œdème bilatéral des pieds et jambes avec visage atteint. L’aspect+++ dans le guide2026 est un critère d’hospitalisation immédiate en MAS. Le poids apparemment préservé n’annule pas le signe.','Examiner danger et appétit, stabiliser, puis rechercher causes et comorbidités. Ne pas attendre un PB bas pour agir si l’œdème est identifié nutritionnel.',('INT-WHO-EDEMA','INT-WHO-TRIAGE','INT-WHO-IDENT')),
 ('Un petit bras avant six mois','Un nourrisson de trois mois a PB108mm, sans œdème, et une trajectoire de croissance préoccupante. Le seuil<110mm identifie un risque de mauvaise croissance ; il ne suffit pas seul à définir MAS dans le guide2026.','Évaluer P/L, trajectoire, alimentation et dyade. Soutien allaitement et soins sont nécessaires selon évaluation ; ne pas recopier RUTF et prescriptions du circuit6–59mois.',('INT-WHO-IDENT','INT-WHO-INFANT')),
 ('Des œdèmes après reprise alimentaire chez l’adulte','Une personne adulte ayant très peu mangé développe dyspnée et faiblesse après reprise. Rechercher syndrome de renutrition, sepsis et autres défaillances ; vérifier P/K/Mg, glycémie, organes et bilan hydrique selon urgence.','Ce n’est pas un E40 automatique. L’équipe adapte progression, thiamine et substitutions ; aucune dose F75 pédiatrique ne devient un objectif adulte.',('CH-RFS-MECH','CH-RFS-MGMT','INT-GLIM','CH-CIM')),
 ('Albumine basse et protéinurie','Une personne œdémateuse a une albumine basse et une protéinurie. La perte rénale doit être évaluée ; ne pas conclure à un apport protéique insuffisant sur albumine seule.','La dénutrition peut coexister et demande sa propre évaluation. La cause rénale modifie aussi les précautions hydriques et médicamenteuses.',('INT-WHO-EDEMA','INT-GLIM','FI-AMOX'))]
for i,(title,p1,p2,refs) in enumerate(cases,1):add('e40-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p><p>'+p1+'</p><p>'+p2+'</p>',refs)
quiz=[('Le poids normal exclut-il une MAS si l’œdème nutritionnel est présent chez6–59mois ?','Non, l’œdème nutritionnel suffit parmi les critères de ce guide.','Oui, il faut obligatoirement un poids/taille<-3z en plus.','Le liquide peut masquer une perte tissulaire ; la cause de l’œdème doit être évaluée.','INT-WHO-IDENT'),('Dans le guide2026, pieds+jambes+mains correspondent-ils à++ ?','Non, l’extension ailleurs que pieds/jambes relève de+++.','Oui, les mains sont incluses dans++ quelle que soit la version.','Conserver la distribution et la version2026 ;+++ peut modifier l’orientation.','INT-WHO-EDEMA'),('À trois mois, PB108mm suffit-il seul à définir MAS ?','Non, il signale un risque ; le diagnostic de malnutrition aiguë sévère du nourrisson utilise des critères distincts.','Oui, appliquer le seuil de115mm des plus grands.','Avant six mois, œdème nutritionnel ou P/L<-3z définit MAS dans ce guide.','INT-WHO-IDENT'),('Une suspension50mg/mL et une25mg/mL ont-elles le même volume pour400mg ?','Non, 400mg correspond à8mL puis16mL.','Oui, la dose en mg impose toujours le même nombre demL.','Le calcul de volume suit la concentration, après choix de dose et prescription.','FI-AMOX')]
q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz)
